// Airport search over OurAirports (public domain): every airport with an IATA
// code and scheduled passenger service — 4,000+ rows, regenerated by
// scripts/travel/build-airports.mjs. Server-only: the table stays out of the
// client bundle and is queried through /api/travel/airports.

import rows from "./airportsData.json";

export interface Airport {
  iata: string;
  name: string;
  city: string;
  country: string; // ISO 3166-1 alpha-2
  /** 3 large, 2 medium, 1 small. */
  size: number;
}

type Row = [string, string, string, string, number, string];
const TABLE = (rows as Row[]).map(([iata, name, city, country, size, keywords]) => ({
  airport: { iata, name, city, country, size } as Airport,
  name: name.toLowerCase(),
  city: city.toLowerCase(),
  keywords: keywords ? keywords.split(",").map((k) => k.trim().toLowerCase()) : [],
}));

const BY_IATA = new Map(TABLE.map((t) => [t.airport.iata, t.airport]));

export function airportByIata(code: string): Airport | undefined {
  return BY_IATA.get(code.trim().toUpperCase());
}

const fold = (s: string) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();

/**
 * Ranked matches for free text. Scoring, highest first:
 *   exact IATA code · metro code in keywords (LON, NYC, TYO) · city prefix ·
 *   keyword prefix · name word prefix · substring — then larger airports.
 */
export function searchAirportIndex(query: string, limit = 8): Airport[] {
  const q = fold(query);
  if (q.length < 2) return [];
  const scored: Array<{ a: Airport; s: number }> = [];
  for (const t of TABLE) {
    const city = fold(t.city);
    const name = fold(t.name);
    let s = 0;
    if (t.airport.iata.toLowerCase() === q) s = 100;
    else if (q.length === 3 && t.keywords.includes(q)) s = 90;
    else if (city.startsWith(q)) s = 70;
    else if (t.keywords.some((k) => fold(k).startsWith(q))) s = 60;
    else if (name.split(/[\s\-/]+/).some((w) => w.startsWith(q))) s = 50;
    else if (city.includes(q) || name.includes(q)) s = 30;
    if (s) scored.push({ a: t.airport, s: s + t.airport.size });
  }
  return scored
    .sort((x, y) => y.s - x.s || x.a.iata.localeCompare(y.a.iata))
    .slice(0, Math.max(1, Math.min(limit, 20)))
    .map((x) => x.a);
}
